&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with CFD postprocessing tools such as ParaView, Tecplot, StarCCM+, Ansys&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:714,&amp;quot;335559740&amp;quot;:360,&amp;quot;335559991&amp;quot;:357}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with GitLab&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:714,&amp;quot;335559740&amp;quot;:360,&amp;quot;335559991&amp;quot;:357}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
